   336    inline bool sanitize (hb_sanitize_context_t *c, unsigned int count) const
   337    {
   338      TRACE_SANITIZE (this);
   339      if (unlikely (!sanitize_shallow (c, count))) return_trace (false);
   340
   341      /* Note: for structs that do not reference other structs,
   342       * we do not need to call their sanitize() as we already did
   343       * a bound check on the aggregate array size.  We just include
   344       * a small unreachable expression to make sure the structs
   345       * pointed to do have a simple sanitize(), ie. they do not
   346       * reference other structs via offsets.
   347       */
   348      (void) (false && arrayZ[0].sanitize (c));
   349
   350      return_trace (true);
   351    }
   352    inline bool sanitize (hb_sanitize_context_t *c, unsigned int count, const void *base) const
   353    {
   354      TRACE_SANITIZE (this);
   355      if (unlikely (!sanitize_shallow (c, count))) return_trace (false);
   356      for (unsigned int i = 0; i < count; i++)
   357        if (unlikely (!arrayZ[i].sanitize (c, base)))
   358          return_trace (false);
   359      return_trace (true);
   360    }
